from __future__ import annotations
import base64
from hashlib import sha256
from pathlib import Path
import subprocess
import zlib
ROOT=Path(__file__).resolve().parents[1]
TARGET=ROOT/"PrimalitySheafVerification"/"Mock2_FunctionalAnalysis.lean"
EXPECTED_INPUT_SHA256="b8142deb44c984965dae3f047675242a61d373f921ad1e5c4e91e6004f5b86b2"
EXPECTED_OUTPUT_SHA256="e915ca85647cd8887ac4b7e1f84aba44a73d3a56ff04deb64f1b0e7284daf0be"
PATCH_ZLIB_BASE64=""
def file_sha256(path: Path)->str: return sha256(path.read_bytes()).hexdigest()
def main()->int:
    before=file_sha256(TARGET); print(f"input_sha256={before}")
    if before==EXPECTED_OUTPUT_SHA256: print("[pass363] already applied"); return 0
    if before!=EXPECTED_INPUT_SHA256: raise RuntimeError(f"unexpected pass363 input sha256: {before}; expected {EXPECTED_INPUT_SHA256}")
    patch=zlib.decompress(base64.b64decode(PATCH_ZLIB_BASE64))
    subprocess.run(["git","apply","--whitespace=nowarn","-"],cwd=ROOT,input=patch,check=True)
    after=file_sha256(TARGET); print(f"output_sha256={after}")
    if after!=EXPECTED_OUTPUT_SHA256: raise RuntimeError(f"unexpected pass363 output sha256: {after}; expected {EXPECTED_OUTPUT_SHA256}")
    print("[pass363] FunctionalAnalysis density, product action, curved chart, and arithmetic roots repaired")
    return 0
if __name__=="__main__": raise SystemExit(main())
